import os
import random
import struct
from typing import List

# Target data type: raw-bytes (message)
# Used by stubs as FUZZ_PARAM_STR for messages and optional context strings.
# Goal: produce valid, interesting byte sequences covering a wide range of sizes and contents,
# while staying <= 4096 bytes.

MAX_TOTAL = 4096

ASCII_WORDS = [
    b"hello", b"world", b"liboqs", b"signature", b"context", b"quantum", b"post-quantum",
    b"nist", b"falcon", b"dilithium", b"sphincs", b"xmss", b"lms", b"test", b"fuzz",
    b"verify", b"sign", b"message", b"public", b"secret", b"key", b"crypto", b"kem",
]

# Some interesting lengths to trigger different code paths: empty, tiny, typical, large
INTERESTING_LENS = [0, 1, 2, 3, 7, 8, 15, 16, 31, 32, 47, 48, 63, 64, 127, 128, 255, 256, 512, 1024, 1500, 2048, 3072, 4095]

# Structured patterns: repeated bytes, increasing counters, random, mixed ASCII + binary, TLS-like, CBOR-like

def _rand_bytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))

def _pattern_repeat(byte_val: int, n: int) -> bytes:
    return bytes([byte_val & 0xFF]) * n

def _pattern_counter(n: int, start: int = 0) -> bytes:
    return bytes(((start + i) & 0xFF) for i in range(n))

def _pattern_words(r: random.Random, n: int) -> bytes:
    out = bytearray()
    while len(out) < n:
        w = r.choice(ASCII_WORDS)
        out.extend(w + b" ")
    return bytes(out[:n])

def _pattern_mixed(r: random.Random, n: int) -> bytes:
    # Mix ASCII words, random bytes, and counters
    parts: List[bytes] = []
    remaining = n
    ctr = r.randrange(256)
    while remaining > 0:
        pick = r.randrange(5)
        if pick == 0:
            k = min(remaining, r.randint(1, 64))
            parts.append(_rand_bytes(r, k))
            remaining -= k
        elif pick == 1:
            k = min(remaining, r.randint(1, 64))
            parts.append(_pattern_counter(k, ctr))
            ctr = (ctr + k) & 0xFF
            remaining -= k
        elif pick == 2:
            k = min(remaining, r.randint(1, 64))
            parts.append(_pattern_repeat(r.randrange(256), k))
            remaining -= k
        else:
            # words
            w = r.choice(ASCII_WORDS)
            kbytes = (w + b" ")
            k = min(remaining, len(kbytes))
            parts.append(kbytes[:k])
            remaining -= k
    return b"".join(parts)

def _pattern_tlv(r: random.Random, n: int) -> bytes:
    # Simple TLV-like: [type(1)][len(2)][value]
    out = bytearray()
    while len(out) + 3 < n:
        t = r.randrange(0, 8)
        maxv = n - len(out) - 3
        l = r.randint(0, min(128, max(0, maxv)))
        out.append(t)
        out.extend(struct.pack(">H", l))
        out.extend(_rand_bytes(r, l))
    return bytes(out[:n]) if len(out) >= n else bytes(out + bytes(n - len(out)))

def _pattern_cbor_like(r: random.Random, n: int) -> bytes:
    # Very rough CBOR-like with major types 0..7 prefix
    out = bytearray()
    while len(out) < n:
        mt = r.randrange(8) << 5
        ai = r.randrange(24)
        out.append((mt | ai) & 0xFF)
        if len(out) >= n:
            break
        # optionally add data bytes
        extra = r.randint(0, min(32, n - len(out)))
        out.extend(_rand_bytes(r, extra))
    return bytes(out[:n])

def _compose_multi_messages(r: random.Random, parts: List[bytes], delimiter: bytes) -> bytes:
    joined = delimiter.join(parts)
    return joined[:MAX_TOTAL]

def _pick_length(r: random.Random) -> int:
    if r.random() < 0.7:
        L = r.choice(INTERESTING_LENS)
        return min(L, MAX_TOTAL)
    # otherwise arbitrary up to MAX_TOTAL
    return r.randint(0, MAX_TOTAL)

def _make_one(r: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    choice = r.randrange(8)
    if choice == 0:
        return _rand_bytes(r, n)
    elif choice == 1:
        return _pattern_repeat(r.randrange(256), n)
    elif choice == 2:
        return _pattern_counter(n, r.randrange(256))
    elif choice == 3:
        return _pattern_words(r, n)
    elif choice == 4:
        return _pattern_mixed(r, n)
    elif choice == 5:
        return _pattern_tlv(r, n)
    elif choice == 6:
        return _pattern_cbor_like(r, n)
    else:
